  'mpesa': r'''
# yaml-language-server: $schema=../../schema/pack.schema.json
schema: 1
id: mpesa
name: M-Pesa
version: 0.2.0
currency: KES
utc_offset: "+03:00"
senders:
  - MPESA
time_format: "d/M/yy 'at' h:mm a"

# Rules are tried in order and the first match wins, so more specific
# shapes (paybill, with "for account") come before general ones (sent).
rules:
  - id: paybill
    type: paybill
    direction: out
    pattern: '^(?<receipt>[A-Z0-9]{10}) Confirmed\. Ksh(?<amount>[\d,]+\.\d{2}) sent to (?<counterparty>.+?) for account (?<account>\S+) on (?<time>\d{1,2}/\d{1,2}/\d{2} at \d{1,2}:\d{2} [AP]M)\.?\s*New M-PESA balance is Ksh(?<balance>[\d,]+\.\d{2})\.\s*Transaction cost, Ksh(?<fee>[\d,]+\.\d{2})\.'

  - id: sent
    type: sent
    direction: out
    pattern: '^(?<receipt>[A-Z0-9]{10}) Confirmed\. Ksh(?<amount>[\d,]+\.\d{2}) sent to (?<counterparty>.+?)(?: (?<account>0\d{2,3}[\d*]{5,7}))? on (?<time>\d{1,2}/\d{1,2}/\d{2} at \d{1,2}:\d{2} [AP]M)\.?\s*New M-PESA balance is Ksh(?<balance>[\d,]+\.\d{2})\.\s*Transaction cost, Ksh(?<fee>[\d,]+\.\d{2})\.'

  - id: received
    type: received
    direction: in
    pattern: '^(?:Congratulations! )?(?<receipt>[A-Z0-9]{10}) [Cc]onfirmed\.\s*You have received Ksh(?<amount>[\d,]+\.\d{2}) from (?<counterparty>.+?)(?: (?<account>0\d{2,3}[\d*]{5,7}|\d{5,7}))?\.? on (?<time>\d{1,2}/\d{1,2}/\d{2} at \d{1,2}:\d{2} [AP]M)\.?\s*New M-PESA balance is Ksh(?<balance>[\d,]+\.\d{2})\.'

  - id: till
    type: till
    direction: out
    pattern: '^(?<receipt>[A-Z0-9]{10}) Confirmed\. Ksh(?<amount>[\d,]+\.\d{2}) paid to (?<counterparty>.+?)\.? on (?<time>\d{1,2}/\d{1,2}/\d{2} at \d{1,2}:\d{2} [AP]M)\.?\s*New M-PESA balance is Ksh(?<balance>[\d,]+\.\d{2})\.\s*Transaction cost, Ksh(?<fee>[\d,]+\.\d{2})\.'

  - id: withdrawal
    type: withdrawal
    direction: out
    pattern: '^(?<receipt>[A-Z0-9]{10}) Confirmed\.\s*on (?<time>\d{1,2}/\d{1,2}/\d{2} at \d{1,2}:\d{2} [AP]M)\s*Withdraw Ksh(?<amount>[\d,]+\.\d{2}) from (?<account>\d+) - (?<counterparty>.+?) New M-PESA balance is Ksh(?<balance>[\d,]+\.\d{2})\.\s*Transaction cost, Ksh(?<fee>[\d,]+\.\d{2})\.'

  - id: airtime
    type: airtime
    direction: out
    pattern: '^(?<receipt>[A-Z0-9]{10}) [Cc]onfirmed\.\s*You bought Ksh(?<amount>[\d,]+\.\d{2}) of airtime on (?<time>\d{1,2}/\d{1,2}/\d{2} at \d{1,2}:\d{2} [AP]M)\.\s*New M-PESA balance is Ksh(?<balance>[\d,]+\.\d{2})\.\s*Transaction cost, Ksh(?<fee>[\d,]+\.\d{2})\.'

  # Fuliza notices print no transaction time; the engine uses the time the
  # phone received the message.
  - id: fuliza
    type: fuliza
    direction: in
    pattern: '^(?<receipt>[A-Z0-9]{10}) Confirmed\. Fuliza M-(?:PESA|Pesa) amount is Ksh ?(?<amount>[\d,]+\.\d{2})\. Access Fee charged Ksh ?(?<fee>[\d,]+\.\d{2})\.'

  - id: fuliza_repayment
    type: fuliza_repayment
    direction: out
    pattern: '^(?<receipt>[A-Z0-9]{10}) Confirmed\. Ksh ?(?<amount>[\d,]+\.\d{2}) from your M-PESA has been used to (?:fully|partially) pay your outstanding Fuliza M-PESA\..*?M-PESA balance is Ksh ?(?<balance>[\d,]+\.\d{2})\.'

  # "account" holds the receipt of the transaction being reversed. Money
  # comes back to the sender ("credited") or is taken back from the
  # recipient ("debited").
  - id: reversal
    type: reversal
    direction_values:
      credited: in
      debited: out
    pattern: '^(?<receipt>[A-Z0-9]{10})\s+[Cc]onfirmed\. Reversal of transaction (?<account>[A-Z0-9]{10}) has been successfully reversed\s+on (?<time>\d{1,2}/\d{1,2}/\d{2}\s+at \d{1,2}:\d{2} [AP]M)\s+and Ksh(?<amount>[\d,]+\.\d{2}) is (?<direction>credited|debited) (?:to|from) your M-PESA account\.\s*New M-PESA (?:account )?balance is Ksh(?<balance>[\d,]+\.\d{2})\.'

  # M-Shwari savings, typed as the statement pack types them.
  - id: mshwari_deposit
    type: paybill
    direction: out
    pattern: '^(?<receipt>[A-Z0-9]{10}) Confirmed\.\s*Ksh(?<amount>[\d,]+\.\d{2}) transferred to (?<counterparty>M-Shwari) account on (?<time>\d{1,2}/\d{1,2}/\d{2}\s+at \d{1,2}:\d{2} [AP]M)\.\s*M-PESA balance is Ksh(?<balance>[\d,]+\.\d{2})\s*\.\s*New M-Shwari saving account balance is Ksh[\d,]+\.\d{2}\.\s*Transaction cost Ksh\.?\s*(?<fee>[\d,]+\.\d{2})'

  - id: mshwari_withdraw
    type: received
    direction: in
    pattern: '^(?<receipt>[A-Z0-9]{10}) Confirmed\.\s*Ksh(?<amount>[\d,]+\.\d{2}) transferred from (?<counterparty>M-Shwari) account on (?<time>\d{1,2}/\d{1,2}/\d{2}\s+at \d{1,2}:\d{2} [AP]M)\.\s*M-Shwari balance is Ksh[\d,]+\.\d{2}\s*\.\s*M-PESA balance is Ksh(?<balance>[\d,]+\.\d{2})\s*\.\s*Transaction cost Ksh\.?\s*(?<fee>[\d,]+\.\d{2})'

  # Airtime for another number; "account" holds that number.
  - id: airtime_other
    type: airtime
    direction: out
    pattern: '^(?<receipt>[A-Z0-9]{10}) [Cc]onfirmed\.\s*Ksh(?<amount>[\d,]+\.\d{2}) of airtime for (?<account>\d{9,12}) on (?<time>\d{1,2}/\d{1,2}/\d{2}\s+at \d{1,2}:\d{2} [AP]M)\.?\s*New M-PESA balance is Ksh(?<balance>[\d,]+\.\d{2})\.'

  # Cash deposited at an agent.
  - id: deposit
    type: received
    direction: in
    pattern: '^(?<receipt>[A-Z0-9]{10}) Confirmed\.\s*On (?<time>\d{1,2}/\d{1,2}/\d{2}\s+at \d{1,2}:\d{2} [AP]M)\s*Give Ksh(?<amount>[\d,]+\.\d{2}) cash to (?<counterparty>.+?)\s+New M-PESA balance is Ksh(?<balance>[\d,]+\.\d{2})\.'
''',
};

/// The YAML source of every statement pack in `packs/*/statement.yaml`, by id.
const bundledStatementPackSources = <String, String>{
  'mpesa_statement': r'''
# yaml-language-server: $schema=../../schema/statement-pack.schema.json
# The Safaricom M-Pesa full statement (PDF). Column names and detail wording
# follow the public statement layout; fixtures are synthetic.
schema: 1
id: mpesa_statement
institution: mpesa
name: M-Pesa statement
version: 0.2.0
currency: KES
utc_offset: "+03:00"

detect:
  - '^\s*M-?PESA\s+STATEMENT\b'
  - 'Receipt No\.?\s+Completion Time\s+Details'

period: 'Statement Period:?\s+(?<start>\d{1,2} [A-Za-z]{3} \d{4})\s+-\s+(?<end>\d{1,2} [A-Za-z]{3} \d{4})'
period_format: "d MMM yyyy"

columns:
  - key: reference
    header: '^Receipt No\.?$'
    pattern: '^[A-Z0-9]{10}$'
  - key: date
    header: '^Completion Time$'
    format: "yyyy-MM-dd HH:mm:ss"
  - key: description
    header: '^Details$'
  - key: status
    header: '^Transaction Status$'
  - key: money_in
    header: '^Paid In$'
    align: right
  # Withdrawals are printed with a minus sign.
  - key: money_out
    header: '^Withdrawn$'
    align: right
    negative: true
  - key: balance
    header: '^Balance$'
    align: right

row_starts_with: reference
order: detect
completed_status: '^Completed$'
skip:
  - '^Page \d+ of \d+'
  - '^Disclaimer\b'

# A payment's charge is a separate row with the same receipt.
fees:
  description: '^[A-Za-z ]+ Charge$'

# First match wins. Detail wording follows the real statement; counterparty
# names come after the masked phone number, with no dash between them.
rules:
  - id: paybill
    type: paybill
    pattern: '^Pay Bill(?: Online)?(?: Fuliza M-?Pesa)?(?: Online)? to \d+ - (?<counterparty>.+?) Acc\.? ?(?<account>\S.*)$'
  - id: till
    type: till
    pattern: '^Merchant Payment(?: Fuliza M-?Pesa)?(?: Online)? to (?<account>\d+) - (?<counterparty>.+)$'
  # Pochi la Biashara: paying a small business on its phone number.
  - id: small_business
    type: till
    pattern: '^Customer (?:Payment to Small Business|Send Money to Micro SME Business(?: with Fuliza M-?Pesa)?) to - (?<account>\S+) (?<counterparty>.+)$'
  - id: sent
    type: sent
    pattern: '^Customer Transfer(?: Fuliza M-?Pesa)? to - (?<account>\S+) (?<counterparty>.+)$'
  - id: received
    type: received
    pattern: '^Funds received from - (?<account>\S+) (?<counterparty>.+)$'
  - id: business_payment
    type: received
    pattern: '^(?:Business|Promotion) Payment from (?<account>\d+) - (?<counterparty>.+?)(?: via API.*)?$'
  # Money moved in from a bank account.
  - id: from_bank
    type: received
    pattern: '^Transfer from Bank (?<account>\d+) - (?<counterparty>.+?) to Customer via API$'
  # Money market fund through M-Pesa: putting money in, and taking it out.
  - id: unit_trust_in
    type: paybill
    pattern: '^Unit Trust Invest To (?<account>\d+) - (?<counterparty>.+?)(?: by .+)?$'
  - id: unit_trust_out
    type: received
    pattern: '^Unit Trust \S+ From (?<account>\d+) - (?<counterparty>.+?)(?: by .+)?$'
  # M-Shwari savings: deposits leave M-Pesa, withdrawals come back.
  - id: mshwari_deposit
    type: paybill
    pattern: '^M-Shwari Deposit\b'
  - id: mshwari_withdraw
    type: received
    pattern: '^M-Shwari Withdraw\b'
  # Mobile to bank, as "<Bank> M2B Transfer to <paybill> - <bank> for ...".
  - id: to_bank
    type: paybill
    pattern: '^\S+ [A-Z]\d[A-Z] Transfer to (?<account>\d+) - (?<counterparty>.+?)(?: for .*)?$'
  - id: withdrawal
    type: withdrawal
    pattern: '^Customer Withdrawal At Agent Till (?<account>\d+) - (?<counterparty>.+)$'
  - id: airtime
    type: airtime
    pattern: '^(?:Airtime Purchase|Recharge for Customer|Buy Bundles?|Customer Bundle Purchase)\b'
  - id: fuliza
    type: fuliza
    pattern: '^OverDraft of Credit Party\b'
  - id: fuliza_repayment
    type: fuliza_repayment
    pattern: '^OD Loan Repayment\b'
  - id: reversal
    type: reversal
    pattern: '\bReversal\b(?:.* of (?<account>[A-Z0-9]{10})\b)?'

password_hint: mpesa_statement
''',
};
